import{_ as t,o as a,c as n,a6 as o}from"./chunks/framework.CCKCzdWs.js";const g=JSON.parse('{"title":"Zephyr Scale Cloud","description":"Connect Zephyr Scale Cloud to the dashboard and bind a project to a Zephyr project: the region, the token, the catalog of test cases and how tests map onto it.","frontmatter":{"title":"Zephyr Scale Cloud","description":"Connect Zephyr Scale Cloud to the dashboard and bind a project to a Zephyr project: the region, the token, the catalog of test cases and how tests map onto it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/zephyr-scale.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/zephyr-scale.html"}],["meta",{"property":"og:title","content":"Zephyr Scale Cloud | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Connect Zephyr Scale Cloud to the dashboard and bind a project to a Zephyr project: the region, the token, the catalog of test cases and how tests map onto it."}]]},"headers":[],"relativePath":"operate/zephyr-scale.md","filePath":"operate/zephyr-scale.md","lastUpdated":1794417729000}'),s={name:"operate/zephyr-scale.md"};function r(i,e,h,c,d,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="zephyr-scale-cloud" tabindex="-1">Zephyr Scale Cloud <a class="header-anchor" href="#zephyr-scale-cloud" aria-label="Permalink to &quot;Zephyr Scale Cloud&quot;">​</a></h1><p>Connect Zephyr Scale Cloud, the test management app for Jira, to the dashboard, and bind a project to a Zephyr project. Piwi reads the project&#39;s test cases and, once the binding is live, writes a finished run&#39;s results back as one test run (<a href="/features/test-management.html">Results in Zephyr Scale</a>). The connection holds the token in one place, managed by an administrator.</p><p>A connection is instance infrastructure, like an <a href="./integrations.html">issue tracker connection</a>: one row per external system, shared by every project, with its token encrypted at rest with <code>PIWI_SECRET_KEY</code>. Zephyr Scale is never offered as an issue tracker, so a project cannot be bound to it for links or for filing issues.</p><h2 id="connecting-zephyr-scale-cloud" tabindex="-1">Connecting Zephyr Scale Cloud <a class="header-anchor" href="#connecting-zephyr-scale-cloud" aria-label="Permalink to &quot;Connecting Zephyr Scale Cloud&quot;">​</a></h2><ol><li>In Jira, open your profile picture, then <strong>Zephyr API keys</strong>, and create a token. Use a dedicated account, so the token does not end with a person&#39;s access.</li><li><strong>Settings → Integrations → Connect Zephyr Scale Cloud</strong> (administrator only): pick the <strong>Region</strong> your Zephyr Scale Cloud runs in (US, EU, AU or DE), paste the token, and choose <strong>Check</strong>. Then <strong>Save</strong>.</li></ol><p><strong>Check</strong> signs in on the region&#39;s API and lists the projects the token sees, without saving anything. <strong>Test connection</strong> on the saved connection signs in again and records the result on its card. Both give up after about ten seconds, and a host that does not answer in that time is reported as unreachable: check that the server can reach the region&#39;s host through any proxy, firewall or VPN.</p><h2 id="the-region-decides-the-host" tabindex="-1">The region decides the host <a class="header-anchor" href="#the-region-decides-the-host" aria-label="Permalink to &quot;The region decides the host&quot;">​</a></h2><p>Zephyr Scale Cloud runs one API per region, and Piwi calls the host the chosen region names. It never takes a host from the form, so a typed address is ignored and an unknown region is refused. Changing the region of a saved connection asks for the token again, because a token belongs to one region.</p><h2 id="bind-a-project" tabindex="-1">Bind a project <a class="header-anchor" href="#bind-a-project" aria-label="Permalink to &quot;Bind a project&quot;">​</a></h2><p>A project is bound in <strong>Project → Settings → Test management</strong> (Project admin on the project). The section always shows; with no Zephyr Scale connection it says &quot;No test management connection yet&quot; and links to <strong>Settings → Integrations</strong> to add one. Pick the <strong>Connection</strong> and the <strong>Project</strong> key, then <strong>Save</strong>. The binding is kept apart from the issue tracker binding, so saving one never changes the other.</p><ul><li><strong>Enabled</strong> keeps the binding but pauses its use.</li><li><strong>Dry run</strong> is on for a new binding. A run&#39;s page then shows what would be sent and nothing reaches Zephyr Scale; turn it off to send. See <a href="/features/test-management.html">Results in Zephyr Scale</a>.</li><li><strong>Where a test’s case key comes from</strong> is its tags, its external ID, or both. A key is a tag or an ID that matches the project&#39;s test case key pattern, such as <code>SHOP-T123</code>, with no <code>@</code>.</li><li><strong>Runs in scope</strong> picks the branches and environments the binding covers, as the issue tracker binding does.</li><li><strong>Result statuses</strong> name the statuses Piwi uses for a pass, a fail, a flaky test and a test not executed, and how a flaky or skipped test is reported. The pickers list the statuses and folders of the chosen project; typing a name the tool does not list is allowed. A flaky status is needed to report flaky tests as <code>flaky</code>.</li><li><strong>Add the first line of the error</strong> to a failed result is off by default, because an error message can carry data from the application.</li></ul><p>The pickers read Zephyr Scale through the connection, cache what they read for five minutes, and share one request budget with the catalog. A token Zephyr refuses marks the connection <strong>failed</strong> on its card.</p><h3 id="the-test-run-name" tabindex="-1">The test run name <a class="header-anchor" href="#the-test-run-name" aria-label="Permalink to &quot;The test run name&quot;">​</a></h3><p>The <strong>Name</strong> of the test run is a template, <code>Automation · {branch} · {environment} · Piwi #{runId}</code> by default. It must contain <code>{runId}</code>, so each Piwi run has its own name, and may use <code>{branch}</code>, <code>{environment}</code>, <code>{commit}</code>, <code>{date}</code> and <code>{ciBuild}</code>. Any other variable, or a name over 200 characters, is refused.</p><h2 id="the-test-case-catalog" tabindex="-1">The test case catalog <a class="header-anchor" href="#the-test-case-catalog" aria-label="Permalink to &quot;The test case catalog&quot;">​</a></h2><p>Piwi keeps a copy of the project&#39;s test cases, so that a key a test carries can be checked and shown without asking Zephyr each time. The catalog stores each case&#39;s key, name, status and folder, and when it was read. It never stores the objective, the steps or the token.</p><p>A task reads the catalog of every bound project that was not read in the last day. <strong>Refresh catalog</strong>, under the mapping summary, reads it now. A read takes every page before it replaces anything, so a failed read keeps the old catalog; it answers 429 while the connection is rate limited and 502 when Zephyr fails or refuses the token.</p><h2 id="how-tests-map-onto-the-catalog" tabindex="-1">How tests map onto the catalog <a class="header-anchor" href="#how-tests-map-onto-the-catalog" aria-label="Permalink to &quot;How tests map onto the catalog&quot;">​</a></h2><p>Under the form, the <strong>mapping summary</strong> reads the last complete run and the stored catalog, and never calls Zephyr:</p><ul><li>how many tests carry a test case key and how many have none;</li><li>the <strong>keys the catalog does not hold</strong>, up to 20, each with the tests that carry it. Until the catalog has been read no key is called unknown;</li><li>a warning when tags were cut at 20 on some tests in the run, since those tests may be missing a key. The count is shown as &quot;at least N&quot; unless every affected test is listed.</li></ul><p>A tag or external ID that is a test case key also shows a <strong>hover card</strong> in the project&#39;s test lists and on the test pages: the case&#39;s name and status from the catalog, a note when the key is not a case in the project, and when the catalog was read.</p><h2 id="request-rate" tabindex="-1">Request rate <a class="header-anchor" href="#request-rate" aria-label="Permalink to &quot;Request rate&quot;">​</a></h2><p>Zephyr Scale rate limits each token, so Piwi spaces out every call of a connection: the catalog read, the pickers and <strong>Refresh catalog</strong>. The limit is 20 requests a minute per connection. Set <code>PIWI_TEST_MANAGEMENT_REQUESTS_PER_MINUTE</code> (1 to 600) to change it. A 429 from Zephyr pauses the connection for the wait it asks for, or a minute.</p><h2 id="environment-managed-connection" tabindex="-1">Environment-managed connection <a class="header-anchor" href="#environment-managed-connection" aria-label="Permalink to &quot;Environment-managed connection&quot;">​</a></h2><p>Set <code>PIWI_ZEPHYR_API_TOKEN</code>, and optionally <code>PIWI_ZEPHYR_REGION</code> (<code>us</code> by default), to manage the connection from the environment instead. It then shows a lock badge and is read-only in the dashboard: change it by editing the environment and restarting. The token stays in the environment and never enters the database. A region the variable does not name is logged and replaced by <code>us</code>. See <a href="./integrations.html#environment-managed-vs-dashboard-managed">Environment-managed vs dashboard-managed</a> for how the two kinds of connection behave.</p><h2 id="who-can-do-what" tabindex="-1">Who can do what <a class="header-anchor" href="#who-can-do-what" aria-label="Permalink to &quot;Who can do what&quot;">​</a></h2><p>With <a href="./authentication.html">authentication</a> on, creating, checking, testing, editing and deleting a Zephyr Scale connection is administrator-only. Saving a binding, the pickers, the mapping summary and <strong>Refresh catalog</strong> need Project admin on the project; the hover cards need only read access to it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/test-management.html">Results in Zephyr Scale</a>: when a run is sent, what is sent and Sync again</li><li><a href="./integrations.html">Integrations</a>: the Jira Cloud connection and how connections are managed</li><li><a href="./production-checklist.html">Production checklist</a>: <code>PIWI_SECRET_KEY</code>, which encrypts the stored token</li><li><a href="/reference/configuration.html#integrations">Configuration reference</a>: the integration variables</li></ul>',29)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
